{"cards": [{"node_code": "N_842c409b15c05b62", "definition": "研究路面结构在荷载与环境作用下的力学响应、变形特征及功能状态，涵盖抗弯拉、抗剪、抗滑、平整度等关键性能指标及其演化规律。", "boundary": "本节点聚焦于路面结构“承受作用后的表现”，即结构响应与功能状态。边界在于区分“性能表现”与“作用输入”：车辆荷载、温度场等外部因素归入“作用”节点；本节点关注结构在受力后的应力、应变、位移、裂缝扩展及宏观功能指标（如抗滑、平整度）。不包含结构尺寸设计或材料微观机理。", "includes": ["路面结构在荷载下的应力、应变、位移及变形协调分析", "抗弯拉、抗剪、抗滑、平整度、车辙等宏观功能性能指标及评价方法", "路面结构在环境作用下的热响应、湿度响应及性能退化规律"], "excludes": ["车辆轴载、温度场、湿度等外部作用源的统计特征与分布规律（归入“作用”节点）", "路面结构层厚度、材料配比等设计参数确定过程（归入“结构设计”节点）"], "sibling_distinctions": [{"other_code": "N_fba7a56c8a347842", "rule": "本节点关注结构在作用下的响应与功能状态（如变形、抗滑）；兄弟节点关注施加在结构上的外部因素（如荷载、温度）本身。"}, {"other_code": "N_d6c64949d4877fdf", "rule": "本节点关注性能指标的定义、测量及响应规律；兄弟节点关注基于性能目标的结构尺寸与材料选择设计。"}], "cross_boundary_rule": "当研究性能退化机理时，若侧重外部作用对材料的影响归入“作用”；若侧重结构整体功能指标的变化归入本节点。"}, {"node_code": "N_fba7a56c8a347842", "definition": "研究作用于路面结构上的车辆荷载、温度、湿度、冻融等外部因素的物理特征、统计规律及其对路面材料的直接作用机理。", "boundary": "本节点聚焦于路面受到的“外部输入”，即“路面承受什么”。边界在于区分“作用源”与“结构响应”：荷载的大小、分布、频率及环境参数的统计特征归入本节点；结构在荷载下的应力、变形、疲劳寿命计算归入“性能”或“结构设计”节点。不包含路基土体的水文地质作用。", "includes": ["车辆轴载、轮压、冲击荷载的统计特征、分布规律及等效换算方法", "温度场分布、湿度变化、冻融循环等环境因素的物理特征及统计规律", "荷载与环境作用对沥青及混凝土材料性能的直接影响机理"], "excludes": ["路面结构在荷载作用下的应力、应变、位移计算及疲劳寿命预测（归入“性能”或“结构设计”节点）", "路基土体的沉降、稳定性分析及地下水对路基的影响（归入路基工程）"], "sibling_distinctions": [{"other_code": "N_842c409b15c05b62", "rule": "本节点关注施加在结构上的外力与环境因素（输入）；兄弟节点关注结构在受力后的响应与功能状态（输出）。"}, {"other_code": "N_d6c64949d4877fdf", "rule": "本节点关注作用源的物理特征；兄弟节点关注基于作用标准进行结构尺寸与材料的设计。"}], "cross_boundary_rule": "当研究荷载对材料微观结构的影响时，若侧重宏观荷载谱特征归入本节点；若侧重材料在荷载下的微观损伤演化机制，可关联至性能节点，但主挂载依据为“作用源”特征。"}]}
